import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', telephone: '', bio: '',
    tarifs_matieres: []
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      // DÉTERMINATION DE LA ROUTE SELON LE RÔLE
      let route = '';
      if (user?.role === 'professeur') route = '/api/professeurs/me';
      else if (user?.role === 'étudiant') route = '/api/etudiants/me';
      else route = '/api/auth/me'; // ROUTE POUR L'ADMIN

      const res = await api.get(route);

      // On unifie les données (que ça vienne de User ou d'un profil lié)
      const data = res.data;
      setForm({
        ...data,
        user_prenom: data.prenom || data.user_prenom || '',
        user_nom: data.nom || data.user_nom || '',
        ville: data.ville || '',
        telephone: data.telephone || '',
        bio: data.bio || ''
      });

      if (user?.role === 'professeur') {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur de chargement profil :", e);
      setLoading(false);
    }
  };

  const handleInput = (key, val) => setForm(prev => ({ ...prev, [key]: val }));

  async function handleSave() {
    try {
      let route = '';
      if (user?.role === 'professeur') route = '/api/professeurs/me';
      else if (user?.role === 'étudiant') route = '/api/etudiants/me';
      else route = '/api/auth/me';

      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        telephone: form.telephone,
        bio: form.bio,
        ...(user?.role === 'professeur' && { tarifs_complets: form.tarifs_matieres })
      };

      await api.put(route, payload);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil mis à jour !");
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', fontSize: '.9rem', width: '100%', outline: 'none', marginBottom: '10px' };

  if (loading) return <div style={{padding: 50, textAlign: 'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>
      <h2 style={{ fontFamily: 'Syne', marginBottom: 30 }}>⚙️ Paramètres du compte ({user?.role})</h2>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '400px 1fr' : '1fr', gap: 30 }}>

        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20 }}>👤 Informations Personnelles</h3>

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
          <input style={inp} value={form.user_prenom} onChange={e => handleInput('user_prenom', e.target.value)} />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
          <input style={inp} value={form.user_nom} onChange={e => handleInput('user_nom', e.target.value)} />

          <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email</label>
          <input style={{...inp, opacity: 0.6}} value={form.email} readOnly />

          {/* On ne montre Ville et Tel que si ce n'est pas l'admin (pour simplifier) */}
          {user?.role !== 'admin' && (
            <>
              <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
              <input style={inp} value={form.telephone} onChange={e => handleInput('telephone', e.target.value)} placeholder="+216..." />

              <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
              <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
                 <option value="">Sélectionner...</option>
                 {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </>
          )}

          <button onClick={handleSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', border:'none', padding:14, borderRadius:12, fontWeight:600 }}>
             {saved ? '✅ Modifié !' : 'Sauvegarder les modifications'}
          </button>
        </div>
      </div>
    </div>
  );
}
